const TYPES={BB:'戦艦',FBB:'高速戦艦',BBV:'航空戦艦',CV:'正規空母',CVB:'装甲空母',CVL:'軽空母',CVE:'軽空母',CA:'重巡洋艦',CAV:'航空巡洋艦',CL:'軽巡洋艦',CLT:'重雷装巡洋艦',CT:'練習巡洋艦',DD:'駆逐艦',DE:'海防艦',CD:'海防戦艦',AV:'水上機母艦',SS:'潜水艦',SSV:'潜水空母',AS:'潜水母艦',AO:'補給艦',LHA:'揚陸艦',AR:'工作艦',UNKNOWN:'?'};
function counts(fleet){
 const n={BB:0,CV:0,CA:0,CL:0,CLT:0,DD:0,LHA:0};
 for(const k of fleet){if(['BB','FBB','BBV'].includes(k))n.BB++;else if(['CV','CVB','CVL','CVE'].includes(k))n.CV++;else if(['CA','CAV'].includes(k))n.CA++;else if(Object.hasOwn(n,k))n[k]++;}
 return n;
}
// This oracle executes the literal ordered source tables for every k=0..n.
// It does not reuse the product's all/some-reading algebra or its condition DSL.
function sourceNode(node,n){
 if(node==='START'){if(n.CV>=1)return {to:'A',priority:1};if(n.CLT>=1)return {to:'A',priority:2};if(n.BB>=4)return {to:'A',priority:3};if(n.CL===0)return {to:'A',priority:4};return {to:'B',priority:5};}
 if(node==='B'){if(n.BB>=3)return {to:'C',priority:1};if(n.DD<=1)return {to:'C',priority:2};return {to:'F',priority:3};}
 if(node==='C'){if(n.DD===0)return {to:'E',priority:1};if(n.BB+n.CV>=4)return {to:'E',priority:2};if(n.BB+n.CV+n.CA>=5)return {to:'E',priority:3};if(n.CLT>=2)return {to:'E',priority:4};return {to:'D',priority:5};}
 if(node==='E'){if(n.DD===0)return {to:'I',priority:1};if(n.CL===0)return {to:'I',priority:2};if(n.CV===0)return {to:'I',priority:3};return {to:'H',priority:4};}
 if(node==='I'){if(n.CL===0)return {to:'H',priority:1};if(n.DD>=2)return {to:'J',priority:2};if(n.BB>=1)return {to:'H',priority:3};if(n.CV>=3)return {to:'H',priority:4};if(n.CV+n.CA>=5)return {to:'H',priority:5};return {to:'J',priority:6};}
 throw Error('source node not in this selected-route comparison: '+node);
}
function sourceReadings(fleet){
 const actual=counts(fleet),rows=[];
 for(let k=0;k<=actual.LHA;k++){
  const n={...actual,CV:actual.CV+k},path=[];let at=sourceNode('START',n).to;
  while(at!=='M'){assert.ok(path.length<12);path.push(at);at=Object.hasOwn({A:'C',D:'G',F:'I',H:'G',G:'M',J:'M'},at)?({A:'C',D:'G',F:'I',H:'G',G:'M',J:'M'})[at]:sourceNode(at,n).to;}
  rows.push({k,path:path.join('')+'M'});
 }
 return rows;
}
function sourceStatus(fleet,index){const target=index===0?'ACDGM':'BFIJM',rows=sourceReadings(fleet).map(x=>x.path===target);return rows.every(Boolean)?'ready':rows.some(Boolean)?'manual':'missing';}
function context(){
 const c=vm.createContext({window:{},HD_FS_TYPE_ALIASES:{},hdFEFind:()=>null});vm.runInContext(fs.readFileSync(path.join(root,'map-plans.js'),'utf8'),c);
 const data=vm.runInContext("HD_MAP_ROUTE_REQUIREMENTS['6-5']",c),presets=vm.runInContext("MAP_PLANS['6-5'].presets",c);
 c.hdFERouteRequirementData=p=>data[p.index];
 c.hdFERouteShips=p=>p.ships.map(s=>({ship:s,type:s.type,typeKnown:s.type!=='?',speedInfo:{known:p.rank!=null,rank:p.rank,base:p.rank,group:'source',invalid:[]}}));
 c.hdFEAssigned=()=>[];c.hdFEGameMatch=()=>({status:'ready'});
 c.hdFEScouting=p=>p.score==null||p.hqMissing?{status:'manual',available:false,score:null,detail:'source numeric/HQ input missing'}:{status:'ready',available:true,score:p.score,coef:p.coef};
 for(const n of ['hdFESpeedLabel','hdFEBranchPredicate','hdFERouteContract'])load('fleet-readiness-evaluator.js',n,c);
 const make=(types,index=0,score=index===0?50:35,coef=3,rank=5)=>({map:'6-5',index,routeIndex:index,preset:presets[index],score,coef,rank,ships:types.map((k,i)=>({ship:'source-'+k+'-'+i,type:TYPES[k],items:[]}))});
 const plan=row=>{const i=row.input,p=make(i.fleet,row.index,i.score,i.coef,i.minSpeed);p.hqMissing=Object.hasOwn(i,'HQ')&&i.HQ===null;if(Object.hasOwn(i,'shipLOS')&&i.shipLOS===null)p.score=null;return p};
 return {c,data,presets,make,plan};
}
function completeRouteContext(){
 const x=context(),c=x.c,s=fs.readFileSync(path.join(root,'fleet-suggester.js'),'utf8'),a=s.indexOf('const HD_FS_TYPE_ALIASES='),b=s.indexOf('\n};',a)+3;vm.runInContext(s.slice(a,b),c);
 for(const n of ['hdFSTypeMatches','hdFSRequirementPatterns','hdFSPresetInfo'])load('fleet-suggester.js',n,c);
 c.hdFEInferRoute=()=>({status:'manual'});c.hdFEBranchRoute=()=>({available:false});
 for(const n of ['hdFESpeedTarget','hdFERouteFlagshipOk','hdFERouteBasic','hdFERoute'])load('fleet-readiness-evaluator.js',n,c);
 const make=(types,index=0)=>{const p=x.make(types,index);p.routeInfo=JSON.parse(JSON.stringify(c.hdFSPresetInfo(p.preset)));return p};
 return {...x,make};
}
test('6-5 independent full-route literals connect CV0 upper alternatives and lower alternatives without example locking',()=>{
 const {c,data,plan}=context(),full=sourceCases.filter(x=>x.node==='FULL');assert.equal(full.length,38);
 for(const row of full)assert.equal(c.hdFERouteContract(plan(row)).status,row.expected.status,row.id);
 for(const d of data){assert.equal(d.useExampleScope,false);assert.equal(d.minimumSpeed,undefined);assert.equal(d.los.exemptWhen,undefined);assert.equal(d.los.coef,3);assert.equal(Object.hasOwn(d.los.checks[0],'failBelow'),false);}
 assert.equal(data[0].los.checks[0].safe,50);assert.equal(data[1].los.checks[0].safe,35);
});
test('6-5 LHA source boundaries include interior-only ACDGM and keep consensus and independent known mismatches',()=>{
 const {c,make}=context();assert.equal(lhaCases.length,12);
 for(const row of lhaCases)for(const index of [0,1])assert.equal(c.hdFERouteContract(make(row.input.fleet,index,100)).status,row.expected[index===0?'upperACDGM':'lowerBFIJM'],row.id+'/'+index);
 const fleet=['BB','BB','CL','DD','LHA','LHA'];assert.deepEqual(sourceReadings(fleet),[{k:0,path:'BCDGM'},{k:1,path:'ACDGM'},{k:2,path:'ACEHGM'}]);assert.equal(sourceStatus(fleet,0),'manual');
 for(const fleet of [['BB','BB','CV','CV','DD','UNKNOWN'],['CV','CLT','CLT','CA','DD','UNKNOWN'],['CV','CV','CA','CA','CAV','UNKNOWN']])assert.equal(c.hdFERouteContract(make(fleet,0,null)).status,'missing');
 for(const fleet of [['CV','UNKNOWN','CAV','CL','DD','DD'],['BB','BB','BB','DD','DD','UNKNOWN']])assert.equal(c.hdFERouteContract(make(fleet,1,null)).status,'missing');
});
test('6-5 known six-ship class counts match an independent ordered-table oracle for every possible LHA count',()=>{
 const {c,make}=context(),kinds=['BB','CV','CA','CL','CLT','DD','LHA','AV'];let combinations=0,comparisons=0,allKReadings=0;
 function walk(left,index,fleet){if(index===kinds.length-1){const row=[...fleet,...Array(left).fill(kinds[index])];combinations++;allKReadings+=sourceReadings(row).length;for(const selected of [0,1]){assert.equal(c.hdFERouteContract(make(row,selected,100)).status,sourceStatus(row,selected),JSON.stringify({row,selected}));comparisons++;}return}for(let n=0;n<=left;n++)walk(left-n,index+1,[...fleet,...Array(n).fill(kinds[index])]);}
 walk(6,0,[]);assert.equal(combinations,1716);assert.equal(comparisons,3432);assert.equal(allKReadings,3003);
});
test('6-5 source class controls distinguish CV families, CL/CLT/CT, CA/CAV, DD/DE and named special ship classes',()=>{
 const {c,make}=context();assert.equal(classControls.length,9);
 for(const type of ['CV','CVB','CVL','CVE']){assert.equal(counts([type]).CV,1);assert.equal(c.hdFERouteContract(make(['BB',type,'CV','CAV','CL','DD'],0)).status,'ready');assert.equal(c.hdFERouteContract(make(['BB',type,'CAV','CL','DD','DD'],1)).status,'missing');}
 for(const type of ['CT','CLT','DE','CD','SSV','AS','AO','AV','AR']){assert.equal(counts([type]).CV,0);assert.equal(c.hdFERouteContract(make(['BB','CV','CV','CA',type,'DD'],0)).status,'ready',type+' is a non-CV filler under complete ordered source conditions, not game legality proof');}
 assert.equal(counts(['CA','CAV']).CA,2);assert.equal(counts(['CLT']).CL,0);assert.equal(counts(['CT']).CL,0);assert.equal(counts(['DD','DE','CD']).DD,1);assert.equal(counts(['SSV','AS','AO']).CV,0);
 for(const type of ['CT','CLT'])assert.equal(c.hdFERouteContract(make(['BB','BB','CAV',type,'DD','DD'],1)).status,'missing');
 assert.equal(c.hdFERouteContract(make(['BB','BB','CAV','CL','DD','DE'],1)).status,'missing');
});
test('6-5 ordered START, B, C and I guards retain priority without claiming full off-route execution',()=>{
 const rows=sourceCases.filter(x=>['START','B','C','I'].includes(x.node));assert.equal(rows.length,11);
 for(const row of rows){const r=sourceNode(row.node,counts(row.input.fleet));assert.equal(r.to,row.expected.to,row.id);assert.equal(r.priority,row.expected.priority,row.id);}
 const {c,make}=context();assert.equal(c.hdFERouteContract(make(['BB','BB','CAV','CL','DD','DD'],1)).status,'ready','DD2 at I precedes BB1-to-H');
 assert.equal(c.hdFERouteContract(make(['BB','BB','CA','CAV','DD','DD'],1)).status,'missing','CL0 precedes DD2 at I and START');
});
test('6-5 real scouting preserves safe50/35, unquantified lower random ranges, null inputs and no speed exemption',()=>{
 const {c,make}=context();let hq=120,hullLos=0;c.localStorage={getItem:()=>JSON.stringify({admiralLevel:hq})};c.hdFCProposalShipLos=()=>hullLos;c.hdFEImproveCoef=()=>0;c.hdFEEquipCoef=()=>1;
 load('fleet-readiness-evaluator.js','hdFEScoutingExemption',c);load('fleet-readiness-evaluator.js','hdFEScouting',c);
 const numeric=sourceCases.filter(x=>['G','J'].includes(x.node)&&Number.isFinite(x.input.score)&&x.input.coef===3);assert.equal(numeric.length,7);
 for(const row of numeric){const p=make(row.input.fleet,row.index,row.input.score),items=[{meta:{stats:{索敵:(row.input.score+48)/3}}}],result=c.hdFEScouting(p,items);assert.equal(result.status,row.expected.scoutingStatus,row.id);assert.ok(Math.abs(result.score-row.input.score)<1e-10);assert.equal(result.coef,3);assert.equal(result.notRequired,undefined);p.rank=20;assert.equal(c.hdFEScouting(p,items).status,row.expected.scoutingStatus,'fastest does not exempt scouting');}
 for(const index of [0,1]){const p=make(index===0?['BB','CV','CV','CAV','CL','DD']:['BB','BB','CAV','CL','DD','DD'],index),safe=index===0?50:35,items=[{meta:{stats:{索敵:(safe+48)/3}}}];hq=0;let r=c.hdFEScouting(p,items);assert.equal(r.available,false);assert.equal(r.score,null);assert.equal(r.reason,'sync');hq=120;hullLos=null;r=c.hdFEScouting(p,items);assert.equal(r.available,false);assert.equal(r.score,null);hullLos=0;hq=100;r=c.hdFEScouting(p,items);assert.ok(Math.abs(r.score-(safe+8))<1e-10);hq=120;}
 const original=context();for(const row of sourceCases.filter(x=>['G','J'].includes(x.node)&&x.expected.status==='manual')){const p=original.plan(row),condition={kind:'scoutingValue',min:row.index===0?50:35,coef:3};assert.equal(original.c.hdFEBranchPredicate(condition,original.c.hdFERouteShips(p),p).status,'manual',row.id+' is a numeric-node guard, not an empty-fleet full route');}
});
test('6-5 non-six-hull domain stays unverified without erasing known route mismatches or inventing speed and gear requirements',()=>{
 const {c,make,data}=context();for(const [fleet,index]of [[['BB','CV','CAV','CL','DD'],0],[['BB','CL','DD','DD','DD'],1],[['BB','CV','CV','CAV','CL','DD','DD'],0],[['BB','CL','DD','DD','DD','DD','DD'],1]])assert.equal(c.hdFERouteContract(make(fleet,index,100)).status,'manual');
 assert.equal(c.hdFERouteContract(make(['BB','BB','CV','CV','DD'],0,100)).status,'missing');assert.equal(c.hdFERouteContract(make(['BB','CV','CL','DD','DD'],1,100)).status,'missing');
 for(const d of data){const text=JSON.stringify(d.conditions);assert.equal(text.includes('minSpeed'),false);assert.equal(text.includes('equipmentShips'),false);assert.equal(d.los.exemptWhen,undefined);assert.equal(d.useExampleFlagshipScope,undefined);}
 const notes=data.map(d=>d.notes.join(' '));assert.ok(notes[0].includes('空母0'));for(const text of ['ランダム域','購入必須','勝利','6隻','0〜n隻','装備互換性','出撃2部隊まで'])for(const n of notes)assert.ok(n.includes(text),text);
});
test('6-5 generalized example scope preserves explicit custom requirements, flagship, manual input and saved preset identity',()=>{
 const {c,make,presets}=completeRouteContext(),upper=['BB','BB','CA','CA','DD','DD'],lower=['BB','CA','CAV','CL','DD','DD'];
 for(const [fleet,index]of [[upper,0],[lower,1]]){const p=make(fleet,index),before=JSON.stringify(p);assert.equal(c.hdFERoute(p).status,'ready');assert.equal(JSON.stringify(p),before);assert.equal(p.preset,presets[index]);const canonical=index===0?['BB','CV','CV','CAV','CL','DD']:['BB','BB','CAV','CL','DD','DD'],q=make(canonical,index);q.routeInfo.requirements.push({token:'空母',count:index===0?3:1});assert.equal(c.hdFERoute(q).status,'missing');const f=JSON.parse(before);f.routeInfo.flagship='駆逐';assert.equal(c.hdFERoute(f).status,'missing');const manual=make(canonical,index);manual.routeInfo.conditionManual=true;assert.equal(c.hdFERoute(manual).status,'manual');const noInfo=JSON.parse(before);delete noInfo.routeInfo;assert.equal(c.hdFERoute(noInfo).status,'ready');}
});
test('6-5 selected suggestion info keeps explicit requirements and manual states separate from its canonical routeInfo',()=>{
 const {c,make,data}=completeRouteContext();
 for(const [index,canonical,alternative]of [[0,['BB','CV','CV','CAV','CL','DD'],['BB','BB','CA','CA','DD','DD']],[1,['BB','BB','CAV','CL','DD','DD'],['BB','CA','CAV','CL','DD','DD']]]){
  for(const fleet of [canonical,alternative]){const p=make(fleet,index),info=JSON.parse(JSON.stringify(p.routeInfo));p.suggestion={info:{...info,requirements:[...info.requirements,{token:'空母',count:index===0?3:1}]}};const r=c.hdFERoute(p);assert.equal(r.status,'manual','keep the old conservative manual composite verdict; simple basic counters do not prove every user constraint with unknowns');assert.ok(r.requirements.some(x=>x.token==='空母'&&!x.ok));const manual=make(fleet,index);manual.suggestion={info:{...JSON.parse(JSON.stringify(manual.routeInfo)),requirements:[],conditionManual:true}};assert.equal(c.hdFERoute(manual).status,'manual','chosen unquantified requirement remains manual');const flag=make(fleet,index);flag.suggestion={info:{...JSON.parse(JSON.stringify(flag.routeInfo)),flagship:'駆逐'}};assert.equal(c.hdFERoute(flag).status,'missing');}
  const noOptIn=make(canonical,index);noOptIn.suggestion={info:{...JSON.parse(JSON.stringify(noOptIn.routeInfo)),conditionManual:true}};data[index].useExampleScope=true;assert.equal(c.hdFERoute(noOptIn).status,'manual','without general-example opt-in old conservative path remains');data[index].useExampleScope=false;
 }
});
test('6-5 selected-only requirements with unknown hulls remain manual without erasing known route or flagship mismatch',()=>{
 const {c,make}=completeRouteContext();
 const upper=make(['BB','CV','CA','DD','DD','UNKNOWN'],0);upper.suggestion={info:{...JSON.parse(JSON.stringify(upper.routeInfo)),requirements:[{token:'軽巡',count:1}]}};assert.equal(c.hdFERoute(upper).status,'manual','unknown could be CL; basic count0 is not certain missing');
 const lower=make(['BB','CA','CL','DD','DD','UNKNOWN'],1);lower.suggestion={info:{...JSON.parse(JSON.stringify(lower.routeInfo)),requirements:[{token:'戦艦級',count:2}]}};assert.equal(c.hdFERoute(lower).status,'manual','unknown could supply the second BB');
 const known=make(['BB','BB','CV','CV','DD','UNKNOWN'],0);known.suggestion={info:{...JSON.parse(JSON.stringify(known.routeInfo)),conditionManual:true}};assert.equal(c.hdFERoute(known).status,'missing','known heavy4 C deviation remains');
 const flag=make(['BB','CV','CA','DD','DD','UNKNOWN'],0);flag.suggestion={info:{...JSON.parse(JSON.stringify(flag.routeInfo)),flagship:'駆逐'}};assert.equal(c.hdFERoute(flag).status,'missing','known first BB is not the explicit DD flagship');
});
test('6-5 audit rows match independent source contracts and keep safe-domain and recommendation limits explicit',()=>{
 const {data}=context(),audit=JSON.parse(fs.readFileSync(path.join(root,'docs/route-goal-guidance-audit.json'),'utf8'));assert.equal(audit.rows.length,59);
 assert.notEqual(data[0].equipmentKinds,data[1].equipmentKinds,'route kinds must not share the mutable map-default array');assert.equal(data[0].equipmentKinds.includes('対潜'),false,'upper selected A/C/D/G has no B/E ASW encounter');assert.equal(data[1].equipmentKinds.includes('対潜'),true,'lower route keeps B ASW combat recommendation scope');
 for(const index of [0,1]){const row=audit.rows.find(x=>x.id==='6-5/'+index+'/default'),expected=expectedContracts[index];assert.equal(row.verification,'partial');for(const [k,key]of [['conditions','conditions'],['scouting','los'],['notes','notes'],['equipmentKinds','equipmentKinds']]){assert.deepEqual(row[k],expected[k]);assert.deepEqual(JSON.parse(JSON.stringify(data[index][key])),expected[k]);}assert.equal(row.scouting.checks[0].failBelow,undefined);assert.match(row.guidanceAudit['索敵'].detail,/ランダム域不詳.*failBelowなし/);assert.match(row.guidanceAudit['推奨セット'].detail,/購入数量ではない/);}
});
